// === Tab: mySketch.js ===
/*
It is a 2D shader made for the weekly Creative Coding Challenge
(https://openprocessing.org/curation/78544) on the theme "Spikes".

Spikes are not the main theme here; however, they can be seen in
the windblown tips of the hair, the hill tops and the suggested
vegetation. I get the impression that the sharp details make the
image appear even softer.

Interaction:
- Space Bar: Pause/Play
- Mouse Wheel: Forward / Backward in time
- Mouse Move: Panoramic view across the mountain ridge
*/

const scale = Math.max(1, devicePixelRatio / 2)
let theShader, moves=[0,0], wheelDelta = 0, wheelOffset = 0, pause = false, paused = 0, time = 0;

function preload(){
	theShader = loadShader('https://openprocessing.org/sketch/2993385/files/vert.glsl', 'frag.glsl')
}

function setup() {
	pixelDensity(scale)
	createCanvas(windowWidth, windowHeight, WEBGL)
}

function windowResized() {
	pixelDensity(scale)
	resizeCanvas(windowWidth, windowHeight)
}

function mouseMove() {
	if (!((window.isBeat || false) || (typeof window.is_silent !== 'undefined' ? !window.is_silent : mouseIsPressed))) return
	moves[0] += ((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))) - (window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))) * scale
	moves[1] += ((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))) - (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))) * scale
}

function mouseWheel(e) {
	if (wheelDelta * e.deltaY < 0) {
		wheelDelta = e.deltaY
	} else {
		wheelDelta = lerp(wheelDelta, e.deltaY, 0.05)
	}
	wheelOffset += wheelDelta
}

function keyPressed(e) {
	if (e.key === " ") {
		if (!pause) {
			pause = true
		} else {
			pause = false
			paused = millis() - time
		}
	}
}

function draw() {
  mouseMove()
  shader(theShader)
  if (!pause) time = millis() - paused
  theShader.setUniform("resolution", [width * scale, height * scale])
  theShader.setUniform("move", moves)
  theShader.setUniform("wheel", [wheelDelta, wheelOffset])
  theShader.setUniform("time", time / 1000.0)
  rect(0, 0, width, height)
}

// === Tab: vert.glsl ===
#version 300 es 
in vec3 aPosition; void main() { gl_Position=vec4(aPosition*2.-1., 1.0); }

// === Tab: frag.glsl ===
#version 300 es
/*********
* made by Matthias Hurrle (@atzedent)
*/
precision highp float;
out vec4 O;
uniform float time;
uniform vec2 resolution;
uniform vec2 wheel;
uniform vec2 move;
#define FC gl_FragCoord.xy
#define R resolution
#define T (time+wheel.y/1e3)
#define N normalize
#define S smoothstep
#define MN min(R.x,R.y)
#define PI radians(180.)
#define rot(a) mat2(cos((a)-vec4(0,11,33,0)))
#define hue(a) (.5+.5*sin(PI*(a)+vec3(0,1,2)))
#define lum(a) dot(a,vec3(.21,.71,.07))
#define SE(v,a) S(a+1./MN,a-1./MN,v)
float rnd(vec2 a) {
	vec3 p=fract(a.xyx*.1031);
	p+=dot(p,p.yzx+33.33);
	return fract((p.x+p.y)*p.z);
}
float noise(vec2 p) {
	p+=33.;
	vec2 i=floor(p), u=S(i,i+1.,p), k=vec2(1,0);
	float
	a=rnd(i),
	b=rnd(i+k),
	c=rnd(i+k.yx),
	d=rnd(i+k.xx);
	return mix(mix(a,b,u.x),mix(c,d,u.x),u.y);
}
float fbm(vec2 p) {
	float t=.0, a=1., h=.0;
	for (int i; i++<5;) {
		t+=a*noise(p-33.);
		p*=2.;
		a/=2.;
		h+=a;
	}
	return t/h;
}
vec3 figure(vec2 p, out float d) {
	vec3 col=vec3(0);
	if (R.x<R.y) p*=R.x/R.y;
	float
	tips=fbm(p.yy*120.-vec2(0,T)),
	head=SE(length(p),.125+.2*fbm(p+.1+.03*fbm(p-.05*sin(T*2.)-.1*tips))),
	neck=SE(length(vec2(p.x,p.y-clamp(p.y,-.25,.125))),.1),
	back=SE(length(p+vec2(0,.4)),.2+.1*fbm(p+.75+.04*fbm(p-T)));
	vec3
	colh=vec3(.5,.2,.05)-.3*fbm(.04*sin(T)+10.+vec2(sin(sin(T)*.2+p.x*102.+(25.+.125*sin(T*(4.+.05*noise(p+.5*sin(T*.2)))))*sin(p.y*4.-p.x*3.5+.125)),p.y*2.+2.))-.2*sin(p.x*4.-.4),
	coln=vec3(1,.76,.63)-.3*fbm(p*12.),
	colb=vec3(.2,.2,.5)-.2*fbm(p*3.-1.7)+.2*S(.5,.2,distance(sin(2.*fbm(T*.2-p*23.)-(p.x+p.y*.5)*220.),sin((p.x-p.y*.5)*120.)));
	col=mix(col,coln,neck);
	col=mix(col,colb,back);
	col=mix(col,colh+.2+.4*lum(colh*2.)+.25*noise(p.yy*12.),head);
	d=max(head,max(back,neck));
	col=tanh(col*col*col);
	col=max(sqrt(col),max(.05,.125*noise(p*2.)));
	return col;
}
vec3 mountains(vec2 uv) {
	vec3 col=vec3(0);
	float
	d=step(uv.y*8.-3.,noise(2.1+uv.xx*rot(PI/3.)*6.+noise((uv.xx+3.)*rot(PI/2.)*8.+noise((uv.xx+5.123)*rot(PI)*8.+noise(uv.yy*4096.)+noise(uv.xx*1024.))))),
	e=step(uv.y*6.-1.,noise(21.5+uv.xx*2.+.5*noise((uv.xx+5.)*8.+.4*noise(2.+uv.xx*16.+noise(uv*96.+noise(uv.yy*4096.)+10.*noise(uv.xx*2048.))))));
	col+=hue(d*(uv.y*1.2+1.55)-.08);
	col=mix(col,hue(e*(uv.y*1.2+1.45)),e);
	return col;
}
void main() {
	vec2 uv=FC/MN, p=(FC-.5*R)/MN;
	if (R.x<R.y) uv*=R.x/R.y;
	uv*=1.-clamp(dot(p,p)*.2,.0,2.);
	uv.x-=move.x*6.3/MN;
	vec3 col=mountains(uv);
	// clouds
	uv*=vec2(.2,1);
	col=mix(col,vec3(1),min(1.,uv.y-.05)*noise(T*.1-uv*12.+.5*noise(T*.2-uv*24.+.5*noise(uv*48.))));
	col=tanh(col*col*col);
	float d;
	vec3 w=figure(p,d)*S(1.,.0,max(length(p*1.5),.25));
	col=mix(col,w,d);
	// grain
	col-=.02*(sin(FC.x*2.)-sin(FC.y*4.));
	// vignette
	vec2 c=FC/R;
	c*=1.-c.yx;
	float v=c.x*c.y*25.;
	col*=pow(v,.125);
	O=vec4(col,1);
}

